-- EN: Registry-owned schema only. / 中文：仅管理框架自身的数据表。
CREATE TABLE IF NOT EXISTS agent_tasks (task_id text PRIMARY KEY, capability text NOT NULL, input jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', dependencies jsonb NOT NULL DEFAULT '[]', result jsonb, attempts int NOT NULL DEFAULT 0, lease_until timestamptz, agent_id text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_attempts (attempt_id bigserial PRIMARY KEY, task_id text NOT NULL, agent_id text NOT NULL, call_id text NOT NULL UNIQUE, status text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, result jsonb, error text);
CREATE TABLE IF NOT EXISTS agent_events (event_id bigserial PRIMARY KEY, task_id text, event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shared_facts (fact_id bigserial PRIMARY KEY, task_id text NOT NULL, agent_id text NOT NULL, version int NOT NULL, value jsonb NOT NULL, verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id, version));
CREATE TABLE IF NOT EXISTS agent_workers (agent_id text PRIMARY KEY, capability text NOT NULL, lease_until timestamptz NOT NULL, quota int NOT NULL DEFAULT 1, in_flight int NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS call_id text;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS request_id text;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS last_error text;
ALTER TABLE agent_attempts ADD COLUMN IF NOT EXISTS lease_until timestamptz;
ALTER TABLE agent_attempts ADD COLUMN IF NOT EXISTS deadline timestamptz;
ALTER TABLE agent_workers ADD COLUMN IF NOT EXISTS enabled boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS agent_requests (request_id text PRIMARY KEY, plan jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_quota (name text PRIMARY KEY, capacity int NOT NULL CHECK(capacity>0));

CREATE INDEX IF NOT EXISTS agent_tasks_status ON agent_tasks(status);
CREATE INDEX IF NOT EXISTS agent_attempts_status ON agent_attempts(status);

CREATE TABLE IF NOT EXISTS agent_capabilities(name text PRIMARY KEY, description text NOT NULL);
ALTER TABLE agent_capabilities ADD COLUMN IF NOT EXISTS verifier boolean NOT NULL DEFAULT false;
ALTER TABLE agent_capabilities ADD COLUMN IF NOT EXISTS required_input_fields jsonb NOT NULL DEFAULT '[]';
ALTER TABLE agent_capabilities ADD COLUMN IF NOT EXISTS required_output_fields jsonb NOT NULL DEFAULT '[]';
ALTER TABLE agent_capabilities ADD COLUMN IF NOT EXISTS allowed_context_prefixes jsonb NOT NULL DEFAULT '[]';
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS max_attempts int NOT NULL DEFAULT 2;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS priority int NOT NULL DEFAULT 0;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS require_verified_facts boolean NOT NULL DEFAULT false;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS min_fact_confidence double precision;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS min_worker_pass_rate double precision;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS fact_key text;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS fact_ttl_seconds int;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS context_keys jsonb NOT NULL DEFAULT '[]';
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS context_query text;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS task_key text;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS trace_id text;
ALTER TABLE agent_tasks ADD COLUMN IF NOT EXISTS recalled_fact_ids jsonb NOT NULL DEFAULT '[]';
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS review_note text;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS reviewed_at timestamptz;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS fact_key text;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS confidence double precision;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS expires_at timestamptz;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS memory_tier text NOT NULL DEFAULT 'episodic';
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS injected_count int NOT NULL DEFAULT 0;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS accepted_count int NOT NULL DEFAULT 0;
ALTER TABLE shared_facts ADD COLUMN IF NOT EXISTS demoted boolean NOT NULL DEFAULT false;
ALTER TABLE agent_workers ADD COLUMN IF NOT EXISTS consecutive_failures int NOT NULL DEFAULT 0;
ALTER TABLE agent_requests ADD COLUMN IF NOT EXISTS max_tokens bigint;
ALTER TABLE agent_requests ADD COLUMN IF NOT EXISTS max_cost_usd double precision;
ALTER TABLE agent_requests ADD COLUMN IF NOT EXISTS used_tokens bigint NOT NULL DEFAULT 0;
ALTER TABLE agent_requests ADD COLUMN IF NOT EXISTS used_cost_usd double precision NOT NULL DEFAULT 0;
ALTER TABLE agent_requests ADD COLUMN IF NOT EXISTS trace_id text;
ALTER TABLE agent_attempts ADD COLUMN IF NOT EXISTS usage jsonb;
CREATE TABLE IF NOT EXISTS agent_expansions (request_id text NOT NULL, expansion_id text NOT NULL, parent_task_id text NOT NULL, plan jsonb NOT NULL, rewire_dependents boolean NOT NULL DEFAULT false, task_ids jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (request_id, expansion_id));
CREATE TABLE IF NOT EXISTS agent_triggers (trigger_id text PRIMARY KEY, description text NOT NULL DEFAULT '', cron_expr text, interval_seconds int, webhook boolean NOT NULL DEFAULT false, plan jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, last_triggered_at timestamptz, next_run_at timestamptz, total_runs int NOT NULL DEFAULT 0, last_request_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_playbooks (playbook_id text PRIMARY KEY, description text NOT NULL DEFAULT '', source_request_id text, version int NOT NULL DEFAULT 1, plan_template jsonb NOT NULL, tags jsonb NOT NULL DEFAULT '[]', total_runs int NOT NULL DEFAULT 0, last_run_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_harness_genome (genome_id text PRIMARY KEY, version int NOT NULL DEFAULT 1, surfaces jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_harness_ledger (entry_id bigserial PRIMARY KEY, round int NOT NULL DEFAULT 1, target_type text NOT NULL, target_id text NOT NULL, hypothesis text NOT NULL DEFAULT '', target_surfaces jsonb NOT NULL DEFAULT '[]', changed_lines int NOT NULL DEFAULT 0, incumbent_metrics jsonb, candidate_metrics jsonb, verdict text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());

-- Hot-path indexes exclude completed history where possible.
CREATE INDEX IF NOT EXISTS agent_tasks_ready ON agent_tasks(capability,updated_at,task_id) WHERE status='queued';
CREATE INDEX IF NOT EXISTS agent_tasks_priority_ready ON agent_tasks(capability,priority DESC,updated_at,task_id) WHERE status='queued';
CREATE INDEX IF NOT EXISTS agent_tasks_request ON agent_tasks(request_id,task_id);
CREATE INDEX IF NOT EXISTS agent_tasks_recent ON agent_tasks(updated_at DESC);
CREATE INDEX IF NOT EXISTS agent_attempts_running_worker ON agent_attempts(agent_id) WHERE status='running';
CREATE INDEX IF NOT EXISTS shared_facts_key_idx ON shared_facts(fact_key,fact_id DESC) WHERE fact_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS shared_facts_agent_review_idx ON shared_facts(agent_id) WHERE reviewed_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS agent_triggers_due_idx ON agent_triggers(next_run_at) WHERE enabled=true AND next_run_at IS NOT NULL;
